export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  draft?: boolean;
  layout?: string;
  [key: string]: unknown;
}

export interface Page {
  frontmatter: Frontmatter;
  content: string;
  html: string;
  sourcePath: string;
  outputPath: string;
  url: string;
  tags: string[];
  isDraft: boolean;
}

export interface BuildContext {
  pages: Page[];
  publishedPages: Page[];
  tagMap: Map<string, Page[]>;
  siteTitle: string;
  siteUrl: string;
}

export interface CLIOptions {
  source: string;
  templates: string;
  output: string;
  serve: boolean;
  port: number;
  siteTitle: string;
  siteUrl: string;
}

import matter from "gray-matter";
import fs from "node:fs/promises";
import path from "node:path";
import type { Frontmatter, Page } from "./types.js";

const DEFAULT_FRONTMATTER: Frontmatter = {
  title: "Untitled",
  draft: false,
  tags: [],
};

export function parseFrontmatter(raw: string): {
  data: Frontmatter;
  content: string;
} {
  const parsed = matter(raw);
  const data: Frontmatter = {
    ...DEFAULT_FRONTMATTER,
    ...(parsed.data as Partial<Frontmatter>),
  };
  if (typeof data.tags === "string") {
    data.tags = data.tags.split(",").map((t) => t.trim()).filter(Boolean);
  }
  if (!Array.isArray(data.tags)) {
    data.tags = [];
  }
  return { data, content: parsed.content };
}

export async function discoverMarkdownFiles(sourceDir: string): Promise<string[]> {
  const results: string[] = [];

  async function walk(dir: string): Promise<void> {
    const entries = await fs.readdir(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        await walk(fullPath);
      } else if (entry.isFile() && entry.name.endsWith(".md")) {
        results.push(fullPath);
      }
    }
  }

  await walk(sourceDir);
  return results.sort();
}

export function sourceToOutputPath(
  sourcePath: string,
  sourceDir: string,
  outputDir: string,
): string {
  const relPath = path.relative(sourceDir, sourcePath);
  const outputRel = relPath.replace(/\.md$/, ".html");
  if (outputRel === "index.html") {
    return path.join(outputDir, "index.html");
  }
  const dirName = outputRel.replace(/\.html$/, "");
  return path.join(outputDir, dirName, "index.html");
}

export function sourceToUrl(
  sourcePath: string,
  sourceDir: string,
): string {
  const relPath = path.relative(sourceDir, sourcePath);
  const urlBase = relPath.replace(/\.md$/, "");
  if (urlBase === "index" || urlBase === "index.html") return "/";
  const name = path.basename(urlBase, path.extname(urlBase));
  const parent = path.dirname(urlBase);
  if (name === "index") return `/${parent}/`;
  return `/${parent}/${name}/`;
}

export function createPage(
  sourcePath: string,
  sourceDir: string,
  outputDir: string,
  raw: string,
): Page {
  const { data, content } = parseFrontmatter(raw);
  return {
    frontmatter: data,
    content,
    html: "",
    sourcePath,
    outputPath: sourceToOutputPath(sourcePath, sourceDir, outputDir),
    url: sourceToUrl(sourcePath, sourceDir),
    tags: data.tags ?? [],
    isDraft: data.draft === true,
  };
}

import { marked, type Renderer } from "marked";
import hljs from "highlight.js";

const renderer: Renderer = {
  code({ text, lang }: { text: string; lang?: string }): string {
    if (lang && hljs.getLanguage(lang)) {
      try {
        const highlighted = hljs.highlight(text, { language: lang }).value;
        return `<pre><code class="hljs language-${lang}">${highlighted}</code></pre>\n`;
      } catch {
        // fall through to plain code block
      }
    }
    return `<pre><code>${escapeHtml(text)}</code></pre>\n`;
  },
};

marked.use({ renderer });

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

export function markdownToHtml(markdown: string): string {
  return marked.parse(markdown, { async: false }) as string;
}

import Handlebars from "handlebars";
import fs from "node:fs/promises";
import path from "node:path";
import type { Page } from "./types.js";

export interface TemplateEngine {
  render(page: Page, content: string, context: Record<string, unknown>): string;
}

export async function createTemplateEngine(
  templatesDir: string,
): Promise<TemplateEngine> {
  await registerPartials(templatesDir);

  const layoutCache = new Map<string, HandlebarsTemplateDelegate>();

  async function getLayout(name: string): Promise<HandlebarsTemplateDelegate> {
    if (layoutCache.has(name)) return layoutCache.get(name)!;
    const layoutPath = path.join(templatesDir, "layouts", `${name}.hbs`);
    const src = await fs.readFile(layoutPath, "utf-8");
    const compiled = Handlebars.compile(src);
    layoutCache.set(name, compiled);
    return compiled;
  }

  return {
    render(page: Page, content: string, context: Record<string, unknown>) {
      const layoutName = page.frontmatter.layout ?? "default";
      return getLayout(layoutName).then((layout) =>
        layout({
          ...context,
          content,
          page: {
            title: page.frontmatter.title,
            date: page.frontmatter.date,
            tags: page.tags,
            url: page.url,
            ...page.frontmatter,
          },
        }),
      );
    },
  };
}

async function registerPartials(templatesDir: string): Promise<void> {
  const partialsDir = path.join(templatesDir, "partials");
  try {
    const entries = await fs.readdir(partialsDir, { withFileTypes: true });
    for (const entry of entries) {
      if (entry.isFile() && entry.name.endsWith(".hbs")) {
        const name = entry.name.replace(/\.hbs$/, "");
        const src = await fs.readFile(path.join(partialsDir, entry.name), "utf-8");
        Handlebars.registerPartial(name, src);
      }
    }
  } catch {
    // partials directory may not exist, that's ok
  }
}

Handlebars.registerHelper("formatDate", (date: string | undefined) => {
  if (!date) return "";
  const d = new Date(date);
  return d.toLocaleDateString("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
  });
});

Handlebars.registerHelper("rfc822Date", (date: string | undefined) => {
  if (!date) return "";
  return new Date(date).toUTCString();
});

Handlebars.registerHelper("eq", (a: unknown, b: unknown) => a === b);

import Handlebars from "handlebars";
import fs from "node:fs/promises";
import path from "node:path";
import type { BuildContext, Page } from "./types.js";

export async function generateRssFeed(
  ctx: BuildContext,
  templatesDir: string,
): Promise<string> {
  const rssPath = path.join(templatesDir, "rss.hbs");
  let template: string;
  try {
    template = await fs.readFile(rssPath, "utf-8");
  } catch {
    template = defaultRssTemplate();
  }

  const compiled = Handlebars.compile(template);
  const posts = ctx.publishedPages
    .filter((p) => p.frontmatter.date)
    .sort((a, b) =>
      new Date(b.frontmatter.date!).getTime() -
      new Date(a.frontmatter.date!).getTime(),
    )
    .slice(0, 20);

  return compiled({
    site: { title: ctx.siteTitle, url: ctx.siteUrl },
    posts: posts.map((p) => ({
      title: p.frontmatter.title,
      url: ctx.siteUrl + p.url,
      date: p.frontmatter.date,
      html: p.html,
      rfc822Date: p.frontmatter.date
        ? new Date(p.frontmatter.date).toUTCString()
        : "",
    })),
    now: new Date().toUTCString(),
  });
}

function defaultRssTemplate(): string {
  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>{{site.title}}</title>
    <link>{{site.url}}</link>
    <description>{{site.title}}</description>
    <atom:link href="{{site.url}}/feed.xml" rel="self" type="application/rss+xml"/>
    <lastBuildDate>{{now}}</lastBuildDate>
{{#each posts}}
    <item>
      <title>{{title}}</title>
      <link>{{url}}</link>
      <guid isPermaLink="true">{{url}}</guid>
      <pubDate>{{rfc822Date}}</pubDate>
      <description><![CDATA[{{{html}}}]]></description>
    </item>
{{/each}}
  </channel>
</rss>`;
}

import Handlebars from "handlebars";
import fs from "node:fs/promises";
import path from "node:path";
import type { BuildContext } from "./types.js";

export async function generateTagPages(
  ctx: BuildContext,
  templatesDir: string,
): Promise<Map<string, string>> {
  const results = new Map<string, string>();
  const tagTemplatePath = path.join(templatesDir, "tag.hbs");
  let templateSrc: string;
  try {
    templateSrc = await fs.readFile(tagTemplatePath, "utf-8");
  } catch {
    templateSrc = defaultTagTemplate();
  }

  const template = Handlebars.compile(templateSrc);

  for (const [tag, pages] of ctx.tagMap) {
    const html = template({
      site: { title: ctx.siteTitle },
      tag,
      pages: pages.map((p) => ({
        title: p.frontmatter.title,
        url: p.url,
        date: p.frontmatter.date,
        tags: p.tags,
      })),
    });
    results.set(tag, html);
  }

  return results;
}

function defaultTagTemplate(): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>{{site.title}} - Tag: {{tag}}</title>
</head>
<body>
  <h1>Tag: {{tag}}</h1>
  <ul>
  {{#each pages}}
    <li>
      <a href="{{url}}">{{title}}</a>
      {{#if date}}<time>{{date}}</time>{{/if}}
    </li>
  {{/each}}
  </ul>
</body>
</html>`;
}

import fs from "node:fs/promises";
import path from "node:path";
import type { BuildContext, CLIOptions, Page } from "./types.js";
import { discoverMarkdownFiles, createPage } from "./frontmatter.js";
import { markdownToHtml } from "./markdown.js";
import { createTemplateEngine } from "./templates.js";
import { generateRssFeed } from "./rss.js";
import { generateTagPages } from "./tags.js";

export async function build(opts: CLIOptions): Promise<BuildContext> {
  const files = await discoverMarkdownFiles(opts.source);
  const engine = await createTemplateEngine(opts.templates);

  const pages: Page[] = [];
  for (const file of files) {
    const raw = await fs.readFile(file, "utf-8");
    const page = createPage(file, opts.source, opts.output, raw);
    page.html = markdownToHtml(page.content);
    pages.push(page);
  }

  const publishedPages = pages.filter((p) => !p.isDraft);
  publishedPages.sort((a, b) => {
    if (!a.frontmatter.date) return 1;
    if (!b.frontmatter.date) return -1;
    return new Date(b.frontmatter.date!).getTime() -
      new Date(a.frontmatter.date!).getTime();
  });

  const tagMap = buildTagMap(publishedPages);

  const ctx: BuildContext = {
    pages,
    publishedPages,
    tagMap,
    siteTitle: opts.siteTitle,
    siteUrl: opts.siteUrl,
  };

  await fs.rm(opts.output, { recursive: true, force: true });
  await fs.mkdir(opts.output, { recursive: true });

  const globalContext = {
    site: {
      title: opts.siteTitle,
      url: opts.siteUrl,
      pages: publishedPages.map((p) => ({
        title: p.frontmatter.title,
        url: p.url,
        date: p.frontmatter.date,
        tags: p.tags,
      })),
    },
  };

  for (const page of pages) {
    const html = await engine.render(page, page.html, {
      ...globalContext,
      pages: publishedPages.filter((p) => p !== page).map((p) => ({
        title: p.frontmatter.title,
        url: p.url,
        date: p.frontmatter.date,
        tags: p.tags,
      })),
    });
    await fs.mkdir(path.dirname(page.outputPath), { recursive: true });
    await fs.writeFile(page.outputPath, html);
  }

  // Generate tag index pages
  const tagPages = await generateTagPages(ctx, opts.templates);
  for (const [tag, html] of tagPages) {
    const tagDir = path.join(opts.output, "tags", tag);
    await fs.mkdir(tagDir, { recursive: true });
    await fs.writeFile(path.join(tagDir, "index.html"), html);
  }

  // Generate RSS feed
  const rss = await generateRssFeed(ctx, opts.templates);
  await fs.writeFile(path.join(opts.output, "feed.xml"), rss);

  // Generate tag listing page
  if (ctx.tagMap.size > 0) {
    const tagsListHtml = generateTagsListing(ctx);
    const tagsDir = path.join(opts.output, "tags");
    await fs.mkdir(tagsDir, { recursive: true });
    await fs.writeFile(path.join(tagsDir, "index.html"), tagsListHtml);
  }

  return ctx;
}

function buildTagMap(pages: Page[]): Map<string, Page[]> {
  const map = new Map<string, Page[]>();
  for (const page of pages) {
    for (const tag of page.tags) {
      if (!map.has(tag)) map.set(tag, []);
      map.get(tag)!.push(page);
    }
  }
  return map;
}

function generateTagsListing(ctx: BuildContext): string {
  const tags = [...ctx.tagMap.entries()]
    .sort(([a], [b]) => a.localeCompare(b));

  const items = tags.map(([tag, pages]) =>
    `<li><a href="/tags/${tag}/">${tag}</a> (${pages.length})</li>`,
  ).join("\n");

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>${ctx.siteTitle} - Tags</title>
</head>
<body>
  <h1>Tags</h1>
  <ul>${items}</ul>
</body>
</html>`;
}

import http from "node:http";
import fs from "node:fs/promises";
import path from "node:path";
import { WebSocketServer, WebSocket } from "ws";
import chokidar from "chokidar";
import type { CLIOptions } from "./types.js";
import { build } from "./build.js";

const RELOAD_SCRIPT = `
<script>
(function() {
  var ws = new WebSocket('ws://' + location.host + '/__livereload');
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') location.reload();
  };
  ws.onclose = function() {
    setTimeout(function() {
      location.reload();
    }, 2000);
  };
})();
</script>
`;

export async function serve(opts: CLIOptions): Promise<void> {
  await build(opts);

  const wss = new WebSocketServer({ noServer: true });
  const clients = new Set<WebSocket>();

  wss.on("connection", (ws) => {
    clients.add(ws);
    ws.on("close", () => clients.delete(ws));
  });

  function notifyReload() {
    for (const client of clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send("reload");
      }
    }
  }

  const watcher = chokidar.watch(opts.source, {
    ignoreInitial: true,
    awaitWriteFinish: { stabilityThreshold: 300 },
  });

  watcher.on("all", async () => {
    try {
      await build(opts);
      notifyReload();
    } catch (err) {
      console.error("Build error:", err);
    }
  });

  const server = http.createServer(async (req, res) => {
    if (!req.url) {
      res.writeHead(404);
      res.end();
      return;
    }

    let filePath = path.join(opts.output, req.url === "/" ? "index.html" : req.url);

    try {
      const stat = await fs.stat(filePath);
      if (stat.isDirectory()) {
        filePath = path.join(filePath, "index.html");
      }
    } catch {
      res.writeHead(404);
      res.end("Not found");
      return;
    }

    try {
      const content = await fs.readFile(filePath, "utf-8");
      const injected = filePath.endsWith(".html")
        ? content.replace("</body>", `${RELOAD_SCRIPT}</body>`)
        : content;

      const ext = path.extname(filePath);
      const mimeTypes: Record<string, string> = {
        ".html": "text/html",
        ".css": "text/css",
        ".js": "application/javascript",
        ".xml": "application/xml",
        ".json": "application/json",
        ".png": "image/png",
        ".jpg": "image/jpeg",
        ".svg": "image/svg+xml",
      };

      res.writeHead(200, {
        "Content-Type": mimeTypes[ext] ?? "application/octet-stream",
      });
      res.end(injected);
    } catch {
      res.writeHead(404);
      res.end("Not found");
    }
  });

  server.on("upgrade", (req, socket, head) => {
    if (req.url === "/__livereload") {
      wss.handleUpgrade(req, socket, head, (ws) => {
        wss.emit("connection", ws, req);
      });
    } else {
      socket.destroy();
    }
  });

  server.listen(opts.port, () => {
    console.log(`Dev server running at http://localhost:${opts.port}`);
    console.log(`Watching: ${opts.source}`);
  });
}

#!/usr/bin/env node
import { Command } from "commander";
import path from "node:path";
import type { CLIOptions } from "./types.js";
import { build } from "./build.js";
import { serve } from "./server.js";

const program = new Command();

program
  .name("statik")
  .description("Static site generator from Markdown + Handlebars")
  .option("-s, --source <dir>", "source directory of Markdown files", "content")
  .option("-t, --templates <dir>", "templates directory", "templates")
  .option("-o, --output <dir>", "output directory for generated HTML", "public")
  .option("--serve", "start a dev server with live reload")
  .option("-p, --port <number>", "dev server port", "3000")
  .option("--site-title <title>", "site title (used in feeds)", "My Site")
  .option("--site-url <url>", "site URL (used in feeds)", "http://localhost:3000")
  .parse(process.argv);

async function main() {
  const opts: CLIOptions = {
    source: path.resolve(program.opts().source),
    templates: path.resolve(program.opts().templates),
    output: path.resolve(program.opts().output),
    serve: program.opts().serve,
    port: parseInt(program.opts().port, 10),
    siteTitle: program.opts().siteTitle,
    siteUrl: program.opts().siteUrl,
  };

  if (opts.serve) {
    await serve(opts);
  } else {
    console.log(`Building site from ${opts.source}...`);
    await build(opts);
    console.log(`Site built to ${opts.output}`);
  }
}

main().catch((err) => {
  console.error("Error:", err.message);
  process.exit(1);
});

