    const feed = await fs.readFile(path.join(outputDir, "feed.xml"), "utf-8");
    expect(feed).toContain("<rss");
    expect(feed).toContain("<channel>");
    expect(feed).toContain("<title>TestSite</title>");
    expect(feed).toContain("<item>");
